    public static byte char2Byte(char ch) {
        if (ch >= '0' && ch <= '9') {
            return (byte) (ch - '0');
        }
        if (ch >= 'a' && ch <= 'f') {
            return (byte) ((ch - 'a') + 10);
        }
        if (ch >= 'A' && ch <= 'F') {
            return (byte) ((ch - 'A') + 10);
        }
        return (byte) 0;
    }

