        if (str == null || str.equals("")) {
            return emptybytes;
        }
        byte[] bytes = new byte[str.length() / 2];
        for (int i = 0; i < bytes.length; i++) {
            char high = str.charAt(i * 2);
            char low = str.charAt((i * 2) + 1);
            bytes[i] = (byte) ((char2Byte(high) * 16) + char2Byte(low));
        }
        return bytes;
    }

