public class EditWord extends Activity implements View.OnClickListener {
    private String action;
    private Button cancel;
    private Button confirm;
    private EditText meanning;
    private EditText spelling;
    private Word word;

    @Override // android.app.Activity
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setTitle("编辑生词本");
        setContentView(R.layout.editword);
        Bundle bundle = getIntent().getExtras();
        this.action = bundle.getString("action");
        initWidgets();
    }

    private void initWidgets() {
        this.spelling = (EditText) findViewById(R.id.EditWord_spelling);
        this.cancel = (Button) findViewById(R.id.attention_cancel_button);
        this.confirm = (Button) findViewById(R.id.attention_confirm_button);
        this.meanning = (EditText) findViewById(R.id.EditWord_meanning);
        this.cancel.setOnClickListener(this);
        this.confirm.setOnClickListener(this);
        if (this.action.equals("edit")) {
            Bundle bundle = getIntent().getExtras();
            DataAccess data = new DataAccess(this);
            Word word = data.QueryAttention("ID ='" + bundle.getString("id") + "'", null).get(0);
            this.spelling.setText(word.getSpelling());
            this.meanning.setText(word.getMeanning());
        }
    }

    @Override // android.view.View.OnClickListener
    public void onClick(View v) {
        if (v == this.cancel) {
            finish();
        }
        if (v == this.confirm) {
            if (this.meanning.getText().toString().equals("") || this.spelling.getText().toString().equals("")) {
                Toast.makeText(this, "信息不能为空", 0).show();
                return;
            }
            if (this.action.equals("add")) {
                boolean add = true;
                final DataAccess data = new DataAccess(this);
                ArrayList<Word> words = data.QueryAttention(null, null);
                for (int i = 0; i < words.size(); i++) {
                    if (this.spelling.getText().toString().equals(words.get(i).getSpelling())) {
                        add = false;
                        Log.i("thesame", new StringBuilder().append(i).toString());
                        this.word = words.get(i);
                    }
                }
                if (!add) {
                    Dialog dialog = new AlertDialog.Builder(this).setIcon(R.drawable.dialog_icon).setTitle("该单词已存在").setMessage("生词本中有这个单词，要覆盖掉它吗？").setPositiveButton("确定", new DialogInterface.OnClickListener() { // from class: com.wphm.englishgaokao.activitys.EditWord.1
                        @Override // android.content.DialogInterface.OnClickListener
                        public void onClick(DialogInterface dialog2, int whichButton) {
                            EditWord.this.word.setSpelling(EditWord.this.spelling.getText().toString());
                            EditWord.this.word.setMeanning(EditWord.this.meanning.getText().toString());
                            data.UpdateAttention(EditWord.this.word);
                            EditWord.this.finish();
                        }
                    }).setNegativeButton("取消", new DialogInterface.OnClickListener() { // from class: com.wphm.englishgaokao.activitys.EditWord.2
                        @Override // android.content.DialogInterface.OnClickListener
                        public void onClick(DialogInterface dialog2, int whichButton) {
                        }
                    }).create();
                    dialog.show();
                }
                if (add) {
                    Word word1 = new Word();
                    word1.setMeanning(this.meanning.getText().toString());
                    word1.setSpelling(this.spelling.getText().toString());
                    word1.setPhonetic_alphabet(" ");
                    data.InsertIntoAttention(word1);
                    finish();
                    return;
                }
                return;
            }
            if (this.action.equals("edit")) {
                new Bundle();
                Bundle bundle = getIntent().getExtras();
                DataAccess data2 = new DataAccess(this);
                Word word = data2.QueryAttention("ID = '" + bundle.getString("id") + "'", null).get(0);
                word.setMeanning(this.meanning.getText().toString());
                word.setSpelling(this.spelling.getText().toString());
                data2.UpdateAttention(word);
                finish();
            }
        }
    }
}

