package com.wphm.englishgaokao.activitys;

    private void initWidgets() {
        this.add = (Button) findViewById(R.id.add);
        this.add.setOnClickListener(this);
        this.info = (TextView) findViewById(R.id.info);
        this.nextone = (Button) findViewById(R.id.nextone);
        this.nextone.setOnClickListener(this);
        this.notremember = (Button) findViewById(R.id.notremember);
        this.notremember.setOnClickListener(this);
        this.remember = (Button) findViewById(R.id.remember);
        this.remember.setOnClickListener(this);
        this.right = (Button) findViewById(R.id.right);
        this.right.setOnClickListener(this);
        this.spelling = (TextView) findViewById(R.id.spelling);
        this.wrong = (Button) findViewById(R.id.wrong);
        this.wrong.setOnClickListener(this);
        Typeface tf = Typeface.createFromAsset(getAssets(), "fonts/SEGOEUI.TTF");
        this.info.setTypeface(tf);
        this.tts = new TextToSpeech(this, this.ttsInitListener);
        new DisplayMetrics();
        DisplayMetrics dm = getApplicationContext().getResources().getDisplayMetrics();
        int screenWidth = dm.widthPixels;
        this.add.setWidth(screenWidth / 3);
        this.nextone.setWidth((screenWidth / 3) * 2);
        this.notremember.setWidth(screenWidth / 3);
        this.remember.setWidth(screenWidth / 3);
        this.right.setWidth(screenWidth / 3);
        this.wrong.setWidth(screenWidth / 3);
    }

package com.wphm.englishgaokao.activitys;

    public void onClick(View v) {
        if (v == this.speak) {
            this.tts.speak(this.list.get(this.currentnum).getSpelling(), 1, null);
        }
        if (v == this.remember) {
            this.wrong.setVisibility(0);
            this.right.setVisibility(0);
            this.remember.setVisibility(8);
            this.notremember.setVisibility(8);
            this.info.setText(String.valueOf(this.list.get(this.currentnum).getPhonetic_alphabet()) + "\n" + this.list.get(this.currentnum).getMeanning());
        }
        if (v == this.notremember) {
            this.nextone.setVisibility(0);
            this.remember.setVisibility(8);
            this.notremember.setVisibility(8);
            this.info.setText(String.valueOf(this.list.get(this.currentnum).getPhonetic_alphabet()) + "\n" + this.list.get(this.currentnum).getMeanning());
        }
        if (v == this.right) {
            this.currentnum++;
            UpdateView();
        }
        if (v == this.wrong || v == this.nextone) {
            new Word();
            Word word = this.list.get(this.currentnum);
            this.list.add(word);
            this.currentnum++;
            UpdateView();
        }
        if (v == this.add) {
            DataAccess data = new DataAccess(this);
            new ArrayList();
            ArrayList<Word> attention = data.QueryAttention("SPELLING ='" + this.list.get(this.currentnum).getSpelling() + "'", null);
            if (attention.size() == 0) {
                data.InsertIntoAttention(this.list.get(this.currentnum));
                Toast.makeText(this, "已加入生词本", 0).show();
            } else {
                Toast.makeText(this, "生词本中已包含这个单词！", 0).show();
            }
        }
    }

package com.wphm.englishgaokao.activitys;

    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.reviewlayout);
        this.currentnum = 0;
        new Bundle();
        Bundle bundle = getIntent().getExtras();
        this.listnum = bundle.getString("list");
        setTitle("复习" + Constants.TITLE_LIST + this.listnum);
        DataAccess data = new DataAccess(this);
        this.list = data.QueryWord("LIST = '" + this.listnum + "'", null);
        initWidgets();
        UpdateView();
    }

