            SharedPreferences setting = Review.this.getSharedPreferences("wordroid.model_preferences", 0);
            if (setting.getString("category", "1").equals("2")) {
                loc = new Locale("us");
            }
            if (Review.this.tts.isLanguageAvailable(loc) == 0) {
                Review.this.tts.setLanguage(loc);
            }
            Review.this.tts.setOnUtteranceCompletedListener(Review.this.ttsUtteranceCompletedListener);
        }

