    public List<Map<String, Object>> getData(String tag) {
        List<Map<String, Object>> list = new ArrayList<>();
        if (tag.equals("shouldreview")) {
            for (int i = 0; i < this.wordlist.size(); i++) {
                if (this.wordlist.get(i).getShouldReview().equals("1")) {
                    Map<String, Object> map = new HashMap<>();
                    map.put("label", String.valueOf(Constants.TITLE_LIST) + this.wordlist.get(i).getList());
                    map.put("times", "已复习次数：" + this.wordlist.get(i).getReview_times());
                    map.put("lasttime", "上次复习时间：" + this.wordlist.get(i).getReviewTime());
                    map.put("image", Integer.valueOf(android.R.drawable.btn_star_big_on));
                    list.add(map);
                }
            }
        } else if (tag.equals("alllists")) {
            for (int i2 = 0; i2 < this.wordlist.size(); i2++) {
                Map<String, Object> map2 = new HashMap<>();
                map2.put("label", String.valueOf(Constants.TITLE_LIST) + this.wordlist.get(i2).getList());
                if (this.wordlist.get(i2).getLearned().equals("0")) {
                    map2.put("state", "状态：未学习  ");
                    map2.put("image", Integer.valueOf(android.R.drawable.btn_star_big_off));
                } else if (this.wordlist.get(i2).getShouldReview().equals("1")) {
                    map2.put("state", "状态：该复习了！ ");
                    map2.put("image", Integer.valueOf(android.R.drawable.btn_star_big_on));
                } else if (Integer.parseInt(this.wordlist.get(i2).getReview_times()) >= 5) {
                    map2.put("state", "状态：复习已完成！ ");
                    map2.put("image", Integer.valueOf(android.R.drawable.btn_star_big_off));
                } else {
                    map2.put("state", "状态：暂不需复习  ");
                    map2.put("image", Integer.valueOf(android.R.drawable.btn_star_big_off));
                }
                list.add(map2);
            }
        } else if (tag.equals("plan")) {
            new ArrayList();
            OperationOfBooks OOB = new OperationOfBooks();
            ArrayList<ArrayList<String>> result = OOB.GetPlan(this.week, this);
            for (int i3 = 0; i3 < 7; i3++) {
                Map<String, Object> map3 = new HashMap<>();
                map3.put("date", result.get(i3).get(0));
                SimpleDateFormat f = new SimpleDateFormat("yyyy-MM-dd");
                Date date = null;
                try {
                    date = f.parse(result.get(i3).get(0));
                } catch (ParseException e) {
                    e.printStackTrace();
                }
                Calendar calendar = Calendar.getInstance();
                calendar.setTime(date);
                String lists = "复习内容：";
                String day = "星期";
                switch (calendar.get(7)) {
                    case 1:
                        day = String.valueOf("星期") + "一  ";
                        break;
                    case 2:
                        day = String.valueOf("星期") + "二  ";
                        break;
                    case 3:
                        day = String.valueOf("星期") + "三  ";
                        break;
                    case 4:
                        day = String.valueOf("星期") + "四  ";
                        break;
                    case 5:
                        day = String.valueOf("星期") + "五  ";
                        break;
                    case 6:
                        day = String.valueOf("星期") + "六  ";
                        break;
                    case 7:
                        day = String.valueOf("星期") + "日  ";
                        break;
                }
                map3.put("day", day);
                for (int j = 1; j < result.get(i3).size(); j++) {
                    lists = (String.valueOf(lists) + result.get(i3).get(j) + " ").replaceAll("List", Constants.TITLE_LIST_REVIEW);
                }
                if (result.get(i3).size() == 1) {
                    map3.put("image", Integer.valueOf(R.drawable.plan_off));
                } else {
                    map3.put("image", Integer.valueOf(R.drawable.plan_on));
                }
                map3.put("lists", lists);
                list.add(map3);
            }
        }
        return list;
    }

