                    e.printStackTrace();
                }
                Calendar calendar = Calendar.getInstance();
                calendar.setTime(date);
                String lists = "复习内容：";
                String day = "星期";
                switch (calendar.get(7)) {
                    case 1:
                        day = String.valueOf("星期") + "一  ";
                        break;
                    case 2:
                        day = String.valueOf("星期") + "二  ";
                        break;
                    case 3:
                        day = String.valueOf("星期") + "三  ";
                        break;
                    case 4:
                        day = String.valueOf("星期") + "四  ";
                        break;
                    case 5:
                        day = String.valueOf("星期") + "五  ";
                        break;
                    case 6:
                        day = String.valueOf("星期") + "六  ";
                        break;
                    case 7:
