    public int[] options(String wordId) {
        int id = Integer.parseInt(wordId);
        int[] optionNum = new int[4];
        int i = 0;
        while (i < 4) {
            optionNum[i] = (int) (Math.random() * this.allList.size());
            if (i > 0) {
                int j = 0;
                while (true) {
                    if (j < i) {
                        if (optionNum[j] != optionNum[i]) {
                            j++;
                        } else {
                            i--;
                            break;
                        }
                    }
                }
            }
            i++;
        }
        boolean isExist = true;
        int k = 0;
        while (true) {
            if (k >= 4) {
                break;
            }
            if (optionNum[k] != id - 1) {
                k++;
            } else {
                isExist = false;
                break;
            }
        }
        if (isExist) {
            this.rightAns = (int) (Math.random() * 4.0d);
            optionNum[this.rightAns] = id - 1;
        }
        return optionNum;
    }

    public int[] random() {
        int[] rand = new int[this.listLength];
        for (int i = 0; i < this.listLength; i++) {
            rand[i] = i;
        }
        for (int i2 = 0; i2 < this.listLength; i2++) {
            int temp = rand[i2];
            int temp1 = (int) (Math.random() * this.listLength);
            rand[i2] = rand[temp1];
            rand[temp1] = temp;
        }
        for (int i3 = 0; i3 < this.listLength; i3++) {
            System.out.println(rand[i3]);
        }
        return rand;
    }

