    public void setNotify(String time, Context context) {
        StringTokenizer st = new StringTokenizer(time, ":, ", false);
        int hour = Integer.parseInt(st.nextToken());
        int minute = Integer.parseInt(st.nextToken());
        Log.i("hour", new StringBuilder().append(hour).toString());
        Log.i("minute", new StringBuilder().append(minute).toString());
        Calendar calendar = Calendar.getInstance();
        if (calendar.get(11) > hour || (calendar.get(11) == hour && calendar.get(12) >= minute)) {
            calendar.add(5, 1);
        }
        calendar.set(11, hour);
        calendar.set(12, minute);
        calendar.set(13, 0);
        calendar.set(14, 0);
        SimpleDateFormat f = new SimpleDateFormat("yyyy-MM-dd");
        Log.i("", f.format(calendar.getTime()));
        long starttime = calendar.getTimeInMillis();
        AlarmManager am = (AlarmManager) context.getSystemService("alarm");
        Intent intent = new Intent(context, (Class<?>) makeNotify.class);
        intent.setAction("shownotify");
        PendingIntent sender = PendingIntent.getBroadcast(context, 0, intent, 0);
        am.cancel(sender);
        Intent intent2 = new Intent(context, (Class<?>) makeNotify.class);
        intent2.setAction("shownotify");
        PendingIntent sender2 = PendingIntent.getBroadcast(context, 0, intent2, 0);
        am.setRepeating(1, starttime, 86400000L, sender2);
        Log.i("it's on", "on");
    }
}

